import 'dart:io'; void main() { final code = File('referencia/pdf.js-master/src/core/glyphlist.js').readAsStringSync(); final exp = RegExp(r't\.([\w.]+) = (0x[0-9a-fA-F]+);'); final out = StringBuffer(); out.writeln('// Copyright 2012 Mozilla Foundation'); out.writeln('// Ported to Dart, 2026. Apache License 2.0.'); out.writeln(''); out.writeln('// Preserve formatting'); out.writeln('// dart format width=5000'); out.writeln(''); out.writeln('final Map<String, int> _glyphsUnicodeMap = {'); for (final match in exp.allMatches(code)) { final key = match.group(1); final val = match.group(2); out.writeln('  \'' + key! + '\': ' + val! + ','); } out.writeln('};'); out.writeln(''); out.writeln('Map<String, int> getGlyphsUnicode() => _glyphsUnicodeMap;'); File('lib/src/core/glyphlist.dart').writeAsStringSync(out.toString()); print('Sucesso!'); }
